let p = ctx.player;
if (!p) return;
let level = p.level;
let look = p.lookAngle;
let eyePos = p.eyePosition;
let aABB = p.boundingBox.inflate(4.5);
let LivingClass = Java.loadClass('net.minecraft.world.entity.LivingEntity');
let entities = level.getEntitiesOfClass(LivingClass, aABB, e => e != p && e.isAlive());

let target = null;
let bestDot = 0.3;
for (let i = 0; i < entities.length; i++) {
    let e = entities[i];
    let toE = e.position().add(0, e.eyeHeight * 0.5, 0).subtract(eyePos).normalize();
    let dot = look.dot(toE);
    if (dot > bestDot) { bestDot = dot; target = e; }
}

if (!target) {
    p.tell('§c[Gladiator] Kein Ziel im Blickfeld!');
    return;
}

let c = global.Stones.getComboCount(target, 'gladiator_combo') || 0;
if (c <= 0) {
    p.tell('§c[Gladiator] Das Ziel hat keine Combo-Punkte!');
    return;
}

let finisherDmg = c * (ctx['finisher_dmg'] || 3.0);

if (typeof target.hurt === 'function') {
    target.hurt(p.damageSources().indirectMagic(p, p), finisherDmg);
} else if (typeof target.attack === 'function') {
    target.attack(finisherDmg);
}

global.Stones.updateCombo(target, 'gladiator_combo', 0, 5, '', 0, 0, 0, '#000000', 0);

global.Stones.setCooldown(p, 'milestone_gladiator', ctx['finisher_cooldown'] || 180);
global.Stones.playSound(p, 'minecraft:entity.dragon_fireball.explode', 'players', 0.8, 1.2);
global.Stones.playSound(p, 'minecraft:entity.player.attack.knockback', 'players', 1.2, 0.5);
global.Stones.spawnParticles(p, 'minecraft:sweep_attack', target.position().add(0, 1, 0), 8, 0.5, 0.5, 0.5, 0.1);
global.Stones.spawnParticles(p, 'minecraft:damage_indicator', target.position().add(0, 1, 0), c * 8, 0.4, 0.4, 0.4, 0.2);
